let wrapper = document.querySelector('.preload');
if (wrapper) {
  window.addEventListener("load", wrapper.classList.remove("preload"));
}

jQuery(function ($) {
 /*---------sticky header---------*/
  function updateStickyHeader() {
    if (window.scrollY >= 50) {
      document.body.classList.add('sticky-header');
    } else {
      document.body.classList.remove('sticky-header');
    }
    if (window.innerWidth < 992) {
      document.body.classList.add('sticky-header');
    }
  }
  $(window).on('resize scroll', updateStickyHeader);
  updateStickyHeader();
  /*---------/sticky header ---------*/
  
  function closeMenu() {
    if ($('body').hasClass("menu-open")) {
      $('body').removeClass("menu-open");
      $('body').removeClass("lock");
      $("#site-navigation").slideToggle();
    }
  }
  /*----Scroll to Hash----*/
  function smoothScrollToHash(hash) {
    closeMenu();
    const $target = $(hash);
    if ($target.length) {
      $('html, body').animate({
        scrollTop: $target.offset().top-100
      }, 800);
    }
  }

  function setScrollTo(item) {
    item.addEventListener('click', (e) => {
      let link = e.target.closest('a');
      const href = link.getAttribute('href');
      const [url, hash] = href.split('#');
      if (hash) {
        const fullHash = '#' + hash;

        if (url === window.location.pathname || url === '' || url === window.location.href.split('#')[0]) {
          e.preventDefault();
          smoothScrollToHash(fullHash);
          history.pushState(null, null, fullHash);
        } else {

        }
      } else if (href.includes("#")) {
        e.preventDefault();
        smoothScrollToHash('html');
      }
    });
  }

  const menuLinks = document.querySelectorAll('.menu .menu-item:not(.menu-item-has-children):not(.modal-link) > a', '.btn');
  menuLinks.forEach(link => {
    setScrollTo(link);
  });
  const btns = document.querySelectorAll('.btn');
  btns.forEach(link => {
    setScrollTo(link);
  });
  const gototop = document.querySelectorAll('.gototop');
  gototop.forEach(link => {
    setScrollTo(link);
  });

  const $menuBtn = $("#mainmenu-toggler");
  const $body = $("body");
  const $menu = $("#site-navigation");
  if ($menuBtn) {
    $menuBtn.on("click", () => {
      $menu.slideToggle();
      $body.toggleClass("menu-open");
      $body.toggleClass("lock");
    });
  }


  $(window).on('load resize', function () {
    var windowWidth = window.innerWidth;
    if (windowWidth >= 992) {
      closeMenu();
      setTimeout(() => {
        $("#site-navigation").css("display", "");
      }, 500);

    }
  });

});

